```{.r .cell-code}
df_septin <- tibble(
  degrees_of_freedom = c(
    model_1$df.residual,
    model_2$df.residual,
    model_3$df.residual,
    model_4$df.residual,
    model_5$df.residual,
    model_6$df.residual,
    model_7$df.residual
  ),
  deviance = c(
    deviance(model_1),
    deviance(model_2),
    deviance(model_3),
    deviance(model_4),
    deviance(model_5),
    deviance(model_6),
    deviance(model_7)
  )
)
gt(df_septin)
```

